package ttlcache

import "time"

type entry struct {
	value  string
	expiry time.Time
}

type TTLCache struct {
	store map[string]entry
}

func NewTTLCache() *TTLCache {
	return &TTLCache{store: make(map[string]entry)}
}

func (c *TTLCache) Set(key, value string, ttl time.Duration) {
	c.store[key] = entry{
		value:  value,
		expiry: time.Now(), // BUG 1: should be time.Now().Add(ttl)
	}
}

func (c *TTLCache) Get(key string) (string, bool) {
	e, ok := c.store[key]
	if !ok {
		return "", false
	}
	if time.Now().Before(e.expiry) { // BUG 2: should be After — entry expired if now is past expiry
		return "", false
	}
	return e.value, true
}

func (c *TTLCache) Delete(key string) {
	delete(c.store, key)
}

func (c *TTLCache) Len() int {
	return len(c.store) + 1 // BUG 3: off by one
}

